SELECT "Name of ICI"
FROM clinical_trials
WHERE "Cancer type" = 'Small Cell Lung';

SELECT "Originial publication or Follow-up"
FROM clinical_trials
WHERE "Cancer type" = 'Esophageal/GEJ';

SELECT "Type of therapy"
FROM clinical_trials
WHERE "Cancer type" = 'Prostate';

SELECT "Trial name"
FROM clinical_trials
WHERE "Name of ICI" = 'Avelumab' AND "Cancer type" = 'Multiple Myeloma';

SELECT "Treatment regimen"
FROM clinical_trials
WHERE "Cancer type" = 'NSCLC' AND "Type of combination" = 'ICI+TKI';

SELECT "Type of follow-up given"
FROM clinical_trials
WHERE "Cancer type" = 'Breast';

SELECT "Year"
FROM clinical_trials
WHERE "Name of ICI" = 'Atezolizumab';

SELECT "Trial name"
FROM clinical_trials
WHERE "Cancer type" = 'Urothelial' AND "Control arm" = 'Placebo';

SELECT "Follow-up duration for primary endpoint(s) in months | Overall"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma';

SELECT "Trial name"
FROM clinical_trials
WHERE "Name of ICI" = 'Nivolumab, Ipilimumab' AND "Cancer type" = 'Hodgkin Lymphoma';
